  h+='<div class="chips">';it.seq.forEach(function(v,k){h+='<button class="ch '+(rev?(v===k?'ok':'bad'):'')+'" data-sq="'+k+'"'+(rev?' disabled':'')+'>'+esc(q.items[v])+'</button>'});
