 ok:function(){tone(660,0,.12,'sine',.13);tone(880,.09,.18,'sine',.13)},no:function(){tone(220,0,.22,'sawtooth',.07,150)},
 streak:function(){[523,659,784,1047].forEach(function(f,i){tone(f,i*.07,.16,'triangle',.11)})},
