  if(rev)g+='<circle cx="'+X(q.pt.x)+'" cy="'+Y(q.pt.y)+'" r="7" fill="none" stroke="var(--ok)" stroke-width="3"/>';
  if(it.pt)g+='<circle cx="'+X(it.pt[0])+'" cy="'+Y(it.pt[1])+'" r="6" fill="'+(rev?(it.ok?'var(--ok)':'var(--bad)'):'var(--pri)')+'" stroke="none"/>';
  var hit='';for(var a=-R;a<=R;a++)for(var b=-R;b<=R;b++)hit+='<rect data-px="'+a+'" data-py="'+b+'" x="'+(X(a)-k/2)+'" y="'+(Y(b)-k/2)+'" width="'+k+'" height="'+k+'" fill="transparent" stroke="none"/>';
